"""Raw Nasdaq Data Link datatables calls, stdlib urllib. The key comes from load_env(); the host from
NDL_BASE_URL (a shell setting), else the real one. Errors carry the HTTP status and the vendor's error
code only, never the URL (it holds the key)."""
from __future__ import annotations

import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request

BASE = os.environ.get("NDL_BASE_URL", "https://data.nasdaq.com")


class ApiError(Exception):
    def __init__(self, code: int, vendor_code: str):
        super().__init__(f"HTTP {code} {vendor_code}")
        self.code, self.vendor_code = code, vendor_code


def _get(path: str, params: dict) -> dict:
    query = urllib.parse.urlencode({**params, "api_key": os.environ["NASDAQ_DATA_LINK_API_KEY"]})
    try:
        with urllib.request.urlopen(f"{BASE}/api/v3/datatables/SHARADAR/{path}?{query}", timeout=60) as r:
            return json.load(r)
    except urllib.error.HTTPError as e:
        try:
            vendor = json.load(e).get("quandl_error", {}).get("code", "") or "?"
        except Exception:
            vendor = "?"
        raise ApiError(e.code, vendor) from None


def metadata(table: str) -> list[str]:
    """Column names of a table, as the API reports them for this key."""
    body = _get(f"{table}/metadata.json", {})
    return [c["name"] for c in body["datatable"]["columns"]]


def rows(table: str, **filters) -> list[dict]:
    """Every row matching `filters` (e.g. ticker="A,B", date__gte="2000-01-01"), following cursors.
    A filter name's "__" becomes "." (date__gte → date.gte)."""
    params = {k.replace("__", "."): v for k, v in filters.items()}
    out, cursor = [], None
    while True:
        body = _get(f"{table}.json", {**params, **({"qopts.cursor_id": cursor} if cursor else {})})
        names = [c["name"] for c in body["datatable"]["columns"]]
        out += [dict(zip(names, r)) for r in body["datatable"]["data"]]
        cursor = body.get("meta", {}).get("next_cursor_id")
        if not cursor:
            return out
        time.sleep(0.5)

