"""yfinance calls for PB-03, one ticker per request and at most one request per second (QR-05), with the
settings AD-03 builds on: full split and dividend adjustment."""
from __future__ import annotations

import time

import yfinance as yf

_last = 0.0


def history(symbol: str, *, start: str | None = None, end: str | None = None, adjusted: bool = True):
    """Daily bars as yfinance returns them; an empty frame means Yahoo returned nothing for the symbol."""
    global _last
    wait = 1.0 - (time.monotonic() - _last)
    if wait > 0:
        time.sleep(wait)
    _last = time.monotonic()
    kwargs = {"start": start, "end": end} if start else {"period": "max"}
    return yf.Ticker(symbol).history(interval="1d", auto_adjust=adjusted, actions=True, **kwargs)


def symbol(ticker: str) -> str:
    """Sharadar's share-class dot (BRK.B) is Yahoo's dash (BRK-B)."""
    return ticker.replace(".", "-")


def rows(frame) -> list[dict]:
    """A frame as rows with ISO dates, for shape_sample()."""
    return [{"date": d.date().isoformat(), **{k: float(v) for k, v in r.items()}} for d, r in frame.iterrows()]

